  public List<string> Log = [];
  public NoteCounts Stock => inner.Stock;
  public Denomination? Jammed => inner.Jammed;
  public bool Dispense(NoteCounts n) { var r = inner.Dispense(n); Log.Add($"D{n}{r}"); return r; }
  public bool Load(NoteCounts n) { var r = inner.Load(n); Log.Add($"L{n}{r}"); return r; }
}
sealed class Flaky(NoteCounts s, Denomination? j, int failAt) : IMoneyDispenser {
  int calls; public NoteCounts Stock { get; private set; } = s; public Denomination? Jammed => j;
  public bool Dispense(NoteCounts n) { if (++calls == failAt) return false; Stock -= n; return true; }
  public bool Load(NoteCounts n) { if (++calls == failAt) return false; Stock += n; return true; }
}
static class P {
  static void Main() {
    long count = 0, diffs = 0;
    Denomination?[] jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten, (Denomination)7];
    var ops = new List<Operation>();
    for (var a = -20; a <= 260; a += 5) ops.Add(new Operation.Withdraw(a));
    for (var f = -1; f <= 2; f++) for (var t = -1; t <= 2; t++) for (var d = -1; d <= 2; d++) ops.Add(new Operation.Deposit(new(f, t, d)));
    foreach (var j in jams)
    for (var sf = -1; sf <= 6; sf++) for (var st = -1; st <= 6; st++) for (var sd = -1; sd <= 6; sd++)
    for (var bal = -5; bal <= 260; bal += 15)
    for (var wt = -10; wt <= 210; wt += 30)
    foreach (var op in ops)
    for (var failAt = 0; failAt <= 3; failAt++) {
      var stock = new NoteCounts(sf, st, sd); var acc = new AccountState(bal, wt);
      IMoneyDispenser mk() => failAt == 0 ? new MoneyDispenser(stock, j) : new Flaky(stock, j, failAt);
      var r1 = new Rec(mk()); var r2 = new Rec(mk());
      var o = new Orig.OrigCashMachine(r1).Execute(acc, op);
      var n = new CashMachine(r2).Execute(acc, op);
      count++;
      if (o != n || !r1.Log.SequenceEqual(r2.Log) || r1.Stock != r2.Stock) {
        if (diffs++ < 10) Console.WriteLine($"DIFF {acc} {stock} {j} {op} fail{failAt}: {o} vs {n}");
      }
    }
    Console.WriteLine($"cas: {count}, différences: {diffs}");
  }
}
